mqd_t mqdes;
char buffer[256];
size_t max_len = 256;
unsigned int priority;
ssize_t bytes_read;
struct timespec abs_timeout;

// Calculate absolute timeout: current time + 5s
clock_gettime(CLOCK_REALTIME, &abs_timeout);
abs_timeout.tv_sec += 5;

bytes_read = mq_timedreceive(
    mqdes,
    buffer,
    max_len,
    &priority,
    &abs_timeout
);
// Returns -1 (and sets errno=ETIMEDOUT) if timeout expires
// while queue is empty.
// Otherwise returns message length.
